    var motivos = { qui: ['Q11', 'Q02', 'Q01', 'Q05'], bio: ['B05', 'B01', 'B09', 'B10'], mat: ['M10', 'M11', 'M05', 'M12'], por: ['P06', 'P07', 'P11', 'P01'] }[MAT] || [];
