        (x.hist || []).concat(y.hist || []).forEach(function (t) { porTs[t.ts] = t; });
        out[id] = { etapa: base.etapa, vence: base.vence, hist: Object.keys(porTs).map(function (k) { return porTs[k]; }).sort(function (p, q) { return p.ts - q.ts; }).slice(-MAX_HIST) };
